// (проверены на Android 09.11.2026: Pixel 6, app 1.0.0 (7) Play, wm density 840 ≈ 205dp, шрифт устройства 1.15; .qa/session-2026-11-09.json).
// Не spec (нет .e2e) — wdio его не запускает. helpers/* не меняем.
//
// Как меряем на Android (дерево UiAutomator хранит ПОЛНЫЙ текст даже при «…», поэтому текст сам по себе ничего не доказывает):
//  • строки: высота элемента при 200% / (высота той же строки при обычной плотности × k), k = 840 / физическая плотность (Pixel 6: 420 → 2).
//    Число строк > числа слов ⇒ где-то слово разорвано (как «היסטו / ריית ה / תפילות / שלי» — 4 строки на 3 слова, #ebcfa6).
//  • внутри экрана: 0 ≤ x, x + w ≤ ширина окна (#67d710 — «דר» за левым краем).
//  • без наложения: рамки соседних элементов не пересекаются (#a4899f).
//  • «…» / «..»: площадь рамки текста при 200% ≥ 0.6 × площадь при обычной плотности × k² (перенос сохраняет площадь, обрезка — нет).
//    Это эвристика: на первом прогоне откалибровать (класс «ошибка теста», смысл проверки не менять). Сам «…» глазами — скрин @manual-check.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { driver } from '@wdio/globals';
import { nodes, type UiNode } from './readiness-1910.ts';

export const QA_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');
export const SHOTS = path.join(QA_DIR, 'screenshots/app-regress/qa-0911');

/** Плотность «200%» для Pixel 6 (физическая 420). Для другого телефона — QA_ZOOM_DENSITY (физическая × 2). */
export const ZOOM_DENSITY = Number(process.env.QA_ZOOM_DENSITY || 840);

function adb(...args: string[]): string {
  const dev = process.env.ANDROID_DEVICE;
  const full = dev ? ['-s', dev, ...args] : args;
  return execFileSync('adb', full, { encoding: 'utf8', timeout: 20000 }).trim();
}

/** Физическая плотность экрана («Physical density: 420»). */
export function physicalDensity(): number {
  const m = adb('shell', 'wm', 'density').match(/Physical density:\s*(\d+)/);
  return m ? Number(m[1]) : 420;
}
/** Текущая плотность (Override, если задана, иначе физическая). */
export function currentDensity(): number {
  const out = adb('shell', 'wm', 'density');
  const o = out.match(/Override density:\s*(\d+)/);
  if (o) return Number(o[1]);
  const p = out.match(/Physical density:\s*(\d+)/);
  return p ? Number(p[1]) : 0;
}
/** Коэффициент зума для пересчёта размеров обычной плотности → 200%. */
export const zoomFactor = () => ZOOM_DENSITY / physicalDensity();

/** Дождаться, что приложение перерисовалось после смены плотности (видна нижняя навигация или заголовок). */
async function waitRelayout(probe: string) {
  await driver.waitUntil(async () => (await nodes()).some((n) => n.label === probe), {
    timeout: 30000, interval: 1000, timeoutMsg: `после смены плотности не видно «${probe}»`,
  });
}

/** Включить «зум 200%» (adb shell wm density 840). Обязательно парой с zoomOff() в after/finally. */
export async function zoomOn(probe = 'בית') {
  adb('shell', 'wm', 'density', String(ZOOM_DENSITY));
  if (currentDensity() !== ZOOM_DENSITY) throw new Error(`wm density не стала ${ZOOM_DENSITY}`);
  await waitRelayout(probe);
}
/** Вернуть плотность (adb shell wm density reset) и проверить, что Override снят. */
export async function zoomOff(probe = 'בית') {
  adb('shell', 'wm', 'density', 'reset');
  const out = adb('shell', 'wm', 'density');
  if (/Override density/.test(out)) throw new Error(`wm density reset не сработал: ${out}`);
  await waitRelayout(probe).catch(() => {});
}

/** Узлы с точным текстом (Android: text или content-desc), только видимые. */
export async function nodesByText(text: string): Promise<UiNode[]> {
  return (await nodes()).filter((n) => n.label === text && n.visible && n.w > 0 && n.h > 0);
}
/** Текстовый узел (TextView) с точным текстом; при нескольких — по фильтру (например, «верх экрана»). */
export async function textNode(text: string, pick: (n: UiNode) => boolean = () => true): Promise<UiNode> {
  let found: UiNode | undefined;
  await driver.waitUntil(async () => {
    found = (await nodesByText(text)).filter((n) => /TextView/.test(n.type)).find(pick);
    return Boolean(found);
  }, { timeout: 20000, interval: 1000, timeoutMsg: `нет текста «${text}»` });
  return found!;
}
/** Узел по регулярному выражению текста. */
export async function textNodeMatching(re: RegExp): Promise<UiNode> {
  let found: UiNode | undefined;
  await driver.waitUntil(async () => {
    found = (await nodes()).find((n) => re.test(n.label) && n.visible && n.w > 0 && n.h > 0);
    return Boolean(found);
  }, { timeout: 20000, interval: 1000, timeoutMsg: `нет текста ${re}` });
  return found!;
}

/** Рамка целиком по ширине внутри экрана (допуск 1 px). */
export async function insideScreenX(n: UiNode) {
  const { width } = await driver.getWindowSize();
  return n.x >= -1 && n.x + n.w <= width + 1;
}
/** Пересекаются ли рамки. */
export function overlaps(a: UiNode, b: UiNode) {
  return a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
}
/** Число строк при 200% по высоте той же строки при обычной плотности (normalH — высота одной строки до зума). */
export function linesAtZoom(zoomH: number, normalH: number, k = zoomFactor()) {
  return Math.round(zoomH / (normalH * k));
}
export const wordCount = (t: string) => t.trim().split(/\s+/).length;
/** Текст не обрезан до «…»/«..»: площадь при 200% ≥ 0.6 × площадь до зума × k². */
export function notTruncated(zoom: UiNode, normal: UiNode, k = zoomFactor()) {
  return zoom.w * zoom.h >= 0.6 * normal.w * normal.h * k * k;
}

export async function saveShot(file: string) {
  fs.mkdirSync(SHOTS, { recursive: true });
  await driver.saveScreenshot(path.join(SHOTS, file));
}
